// Runs the exported scikit-learn pipelines in the browser.
// models.json is generated by `python -m src.export_web_model` in the analysis repo.
import models from './models.json';

export type ModelKey = 'combined' | 'self_removed';
type Value = boolean | number | string;

interface Term {
  kind: 'scaled' | 'onehot' | 'raw';
  col: string;
  coef: number;
  mean?: number;
  scale?: number;
  value?: string;
}

interface LinearModel {
  inputs: string[];
  intercept: number;
  terms: Term[];
}

const MODELS = models as Record<ModelKey, LinearModel>;

const num = (v: Value): number => (typeof v === 'boolean' ? (v ? 1 : 0) : Number(v));

export function predict(key: ModelKey, input: Record<string, Value>) {
  const m = MODELS[key];
  for (const col of m.inputs) {
    if (input[col] === undefined) throw new Error(`Missing input: ${col}`);
  }
  let z = m.intercept;
  for (const t of m.terms) {
    const v = input[t.col];
    let x: number;
    if (t.kind === 'scaled') x = (num(v) - t.mean!) / t.scale!;
    else if (t.kind === 'onehot') x = String(v) === t.value ? 1 : 0;
    else x = num(v);
    z += t.coef * x;
  }
  const probability = 1 / (1 + Math.exp(-z));
  const prediction = probability >= 0.5 ? 1 : 0;
  return { probability, prediction, success_relapse: prediction === 1 ? 'Success' : 'Relapse' };
}
